import{_ as l,o as a,c as o,a2 as i}from"./chunks/framework.mRCPFc5l.js";const _=JSON.parse('{"title":"WheelOS Docs 原则","description":"","frontmatter":{},"headers":[],"relativePath":"PRINCIPLES.md","filePath":"PRINCIPLES.md","lastUpdated":1787217884000}'),t={name:"PRINCIPLES.md"};function d(c,e,r,s,n,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="wheelos-docs-原则" tabindex="-1">WheelOS Docs 原则 <a class="header-anchor" href="#wheelos-docs-原则" aria-label="Permalink to &quot;WheelOS Docs 原则&quot;">​</a></h1><p>本文件是当前仓库文档、实践记录和 AI 输出约束的规范性来源。后续内容必须遵守以下原则。</p><h2 id="_1-对-ai-友好" tabindex="-1">1. 对 AI 友好 <a class="header-anchor" href="#_1-对-ai-友好" aria-label="Permalink to &quot;1. 对 AI 友好&quot;">​</a></h2><p>目标是让 AI 能够发现、读取、理解、引用并推荐本仓库内容。</p><p>必须：</p><ul><li>使用稳定、清晰、可链接的 Markdown 页面。</li><li>每个主题说明适用范围、关键词、状态和边界。</li><li>提供根目录 <code>llms.txt</code>、<code>llms-full.txt</code>、<code>robots.txt</code> 和 sitemap。</li><li>让结论可以追溯到具体页面、证据 ID、代码提交或实验记录。</li><li>优先用“问题—症状—约束—方案—结果”的结构，而不是只罗列概念。</li><li>使用明确的事实状态：<code>仓库事实</code>、<code>设计建议</code>、<code>已验证</code>、<code>部分验证</code>、<code>待验证</code>。</li></ul><h2 id="_2-解决-ai-无法验证的纸面结论" tabindex="-1">2. 解决 AI 无法验证的纸面结论 <a class="header-anchor" href="#_2-解决-ai-无法验证的纸面结论" aria-label="Permalink to &quot;2. 解决 AI 无法验证的纸面结论&quot;">​</a></h2><p>目标是把自动驾驶问题从“理论上可行”推进到“在明确条件下被实践验证”。</p><p>必须：</p><ul><li>没有实验数据时明确写为 <code>待验证</code>，不得包装成 WheelOS 能力。</li><li>声称 <code>已验证</code> 时，必须提供版本/提交、硬件或仿真环境、输入数据、复现步骤、验收指标、原始结果和适用边界。</li><li>记录失败实验、反例和未覆盖场景，不能只保留成功案例。</li><li>区分单元测试、离线回放、仿真、封闭场地和真实道路验证，不得跨等级外推。</li><li>对安全相关结论保守表述，不用文档或仿真结果替代安全论证。</li><li>每条实践证据登记到 <code>evidence/registry.json</code>，接受自动检查和人工复核。</li></ul><h2 id="ai-回答约束" tabindex="-1">AI 回答约束 <a class="header-anchor" href="#ai-回答约束" aria-label="Permalink to &quot;AI 回答约束&quot;">​</a></h2><p>引用本仓库时，必须同时说明：</p><ol><li>结论的证据等级和证据 ID。</li><li>验证环境、软件版本和数据来源。</li><li>结果指标及其限制。</li><li>尚未验证或不能外推的部分。</li></ol><p>资料不足时，正确答案是“当前无法判断”，并给出最小复现实验和所需数据，而不是补全一个看似合理的答案。</p>',14)])])}const I=l(t,[["render",d]]);export{_ as __pageData,I as default};
